import { expect, test, uniqueName } from "../../fixtures";

const INVALID_FIELDS: Array<{ field: string; value: unknown }> = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
];

/** True when the error body names the given field in any of the shapes the API may use. */
function namesField(body: any, field: string): boolean {
  const candidates: unknown[] = [];
  if (Array.isArray(body?.detail)) {
    for (const d of body.detail) candidates.push(d?.loc);
  }
  if (body?.error) {
    candidates.push(body.error.field, body.error.loc, body.error.details, body.error.fields);
  }
  return candidates.some((c) => {
    if (typeof c === "string") return c === field || c.includes(field);
    if (Array.isArray(c)) return c.includes(field) || JSON.stringify(c).includes(`"${field}"`);
    if (c && typeof c === "object") return JSON.stringify(c).includes(`"${field}"`);
    return false;
  });
}

for (const { field, value } of INVALID_FIELDS) {
  test(
    `rejects a vendor with invalid ${field}`,
    { tag: "@VEN-02" },
    async ({ apiAs }) => {
      // Arrange: a valid vendor payload, with only the targeted field made invalid
      const member = await apiAs("member");
      const payload: Record<string, unknown> = {
        name: uniqueName("Ven02 Vendor"),
        category: "software",
        contact_email: "billing@ven02.test",
      };
      payload[field] = value;

      // Act
      const response = await member.post("/api/vendors", { data: payload });

      // Assert
      expect(response.status()).toBe(422);
      const body = await response.json();
      expect(body.error?.code ?? body.code).toBe("validation_error");
      expect(namesField(body, field), `error should name field "${field}"`).toBe(true);
    },
  );
}
